import subprocess, pty, os, select, time, sys

def run_with_pty(cmd, input_data=None):
    master, slave = pty.openpty()
    print(f"PTY master={master} slave={slave}")
    proc = subprocess.Popen(cmd, stdin=slave, stdout=slave, stderr=slave, close_fds=True, cwd="/workspace")
    os.close(slave)
    # set nonblocking?
    import fcntl
    flags = fcntl.fcntl(master, fcntl.F_GETFL)
    fcntl.fcntl(master, fcntl.F_SETFL, flags | os.O_NONBLOCK)
    time.sleep(1.0)
    output = b""
    try:
        while True:
            try:
                data = os.read(master, 4096)
                if not data:
                    break
                output += data
                print(f"read {len(data)} bytes: {data!r}")
            except BlockingIOError:
                break
            except OSError as e:
                print(f"OSError {e}")
                break
    finally:
        pass
    # check if still running, send input?
    poll = proc.poll()
    print(f"poll after 1s: {poll}")
    if poll is None:
        if input_data:
            print(f"sending input {input_data!r}")
            os.write(master, input_data)
            time.sleep(1.0)
            while True:
                try:
                    data = os.read(master, 4096)
                    if not data:
                        break
                    output += data
                    print(f"read2 {len(data)} bytes: {data!r}")
                except BlockingIOError:
                    break
                except OSError as e:
                    print(f"OSError2 {e}")
                    break
            poll = proc.poll()
            print(f"poll after input: {poll}")
        else:
            # try to kill?
            proc.terminate()
            try:
                proc.wait(timeout=2)
            except:
                proc.kill()
    else:
        # process exited, drain remaining
        try:
            while True:
                try:
                    data = os.read(master, 4096)
                    if not data:
                        break
                    output += data
                    print(f"drain {len(data)}: {data!r}")
                except BlockingIOError:
                    break
                except OSError:
                    break
        except Exception as e:
            print(e)
    os.close(master)
    print(f"final output len {len(output)}: {output!r}")
    print(f"returncode {proc.returncode}")

