import subprocess, pty, os, time, fcntl, select

def run_interactive(cmd, inputs, cwd="/tmp/test1", env_extra=None):
    import os, subprocess, pty, time, fcntl
    master, slave = pty.openpty()
    print(f"CMD: {cmd} inputs={inputs}")
    import os as _os
    env = _os.environ.copy()
    env["TERM"] = "xterm"
    if env_extra:
        env.update(env_extra)
    proc = subprocess.Popen(cmd, stdin=slave, stdout=slave, stderr=slave, close_fds=True, cwd=cwd, env=env)
    os.close(slave)
    flags = fcntl.fcntl(master, fcntl.F_GETFL)
    fcntl.fcntl(master, fcntl.F_SETFL, flags | os.O_NONBLOCK)
    output = b""
    def drain(timeout=1.0):
        nonlocal output
        end = time.time() + timeout
        while time.time() < end:
            try:
                data = os.read(master, 4096)
                if data:
                    output += data
                    print(f"  read: {data!r}")
                    end = time.time() + 0.5  # extend on data
                else:
                    break
            except BlockingIOError:
                time.sleep(0.05)
                # check if proc exited
                if proc.poll() is not None:
                    # try one more read
                    time.sleep(0.1)
                    try:
                        data = os.read(master, 4096)
                        if data:
                            output += data
                            print(f"  read after exit: {data!r}")
                    except:
                        pass
                    break
            except OSError as e:
                print(f"  OSError {e}")
                break
            if proc.poll() is not None:
                # drain remaining
                time.sleep(0.2)
                try:
                    while True:
                        try:
                            data = os.read(master, 4096)
                            if not data:
                                break
                            output += data
                            print(f"  drain: {data!r}")
                        except BlockingIOError:
                            break
                        except OSError:
                            break
                except:
                    pass
                break
    drain(2.0)
    for inp in inputs:
        if proc.poll() is not None:
            print(f"  proc already exited with {proc.poll()}")
            break
        print(f"  sending {inp!r}")
        os.write(master, inp.encode() if isinstance(inp, str) else inp)
        time.sleep(0.5)
        drain(1.5)
    # wait
    try:
        proc.wait(timeout=2)
    except:
        proc.terminate()
        try:
            proc.wait(timeout=1)
        except:
            proc.kill()
    # final drain
    try:
        while True:
            try:
                data = os.read(master, 4096)
                if not data:
                    break
                output += data
                print(f"  final: {data!r}")
            except BlockingIOError:
                break
            except OSError:
                break
    except Exception as e:
        print(e)
    os.close(master)
    print(f"  returncode={proc.returncode}")
    print(f"  total output ({len(output)}): {output!r}")
    print()
    return output, proc.returncode

# reset file
open("/tmp/test1/a.txt","w").write("hello world\n")
open("/tmp/test1/b.txt","w").write("hello world hello\n")

print("=== interactive single file, answer Y ===")
run_interactive(["/workspace/executable", "--no-color", "hello", "HELLO", "a.txt"], ["Y\n"])

